import calendar
import datetime
import re

__all__ = ["next_fire"]

# (low, high) bounds for each of the five fields
_BOUNDS = [
    (0, 59),  # minute
    (0, 23),  # hour
    (1, 31),  # day of month
    (1, 12),  # month
    (0, 7),   # day of week (0 and 7 = Sunday)
]

_ITEM_RE = re.compile(r"^(?:(\*)|([0-9]+)|([0-9]+)-([0-9]+))(?:/([0-9]+))?$")


def _parse_field(text, lo, hi):
    """Parse one cron field into a set of integers. Raises ValueError."""
    values = set()
    for item in text.split(","):
        if item == "":
            raise ValueError("empty item in field %r" % text)
        m = _ITEM_RE.match(item)
        if m is None:
            raise ValueError("invalid item %r" % item)
        star, single, ra, rb, step = m.groups()

        if step is not None and single is not None:
            raise ValueError("step without range in item %r" % item)

        if star is not None:
            start, end = lo, hi
        elif single is not None:
            start = end = int(single)
        else:
            start, end = int(ra), int(rb)
            if start > end:
                raise ValueError("range %r has start > end" % item)

        if start < lo or end > hi:
            raise ValueError("value out of range in item %r" % item)

        if step is not None:
            s = int(step)
            if s < 1:
                raise ValueError("step must be at least 1 in item %r" % item)
        else:
            s = 1

        values.update(range(start, end + 1, s))
    return values


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    fields = [f for f in expr.split(" ") if f != ""]
    if len(fields) != 5:
        raise ValueError("expected exactly five fields, got %d" % len(fields))

    sets = [_parse_field(f, lo, hi) for f, (lo, hi) in zip(fields, _BOUNDS)]
    minutes, hours, doms, months, dows = sets

    # Normalise day of week: 7 is Sunday, same as 0.
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    # Can the expression ever fire?  Only a restricted day-of-month that is
    # the sole day criterion can make it impossible (e.g. 31 February).
    if not dom_star and dow_star:
        min_dom = min(doms)
        # Maximum possible length of each month (February: 29 in leap years).
        if not any(min_dom <= (29 if mo == 2 else calendar.monthrange(2001, mo)[1])
                   for mo in months):
            raise ValueError("expression can never fire: %r" % expr)

    return (sorted(minutes), sorted(hours), doms, months, dows,
            dom_star, dow_star)


def _first_time(hours, minutes, lb_h, lb_m):
    """First (hour, minute) >= (lb_h, lb_m) from the sorted lists, or None."""
    for h in hours:
        if h < lb_h:
            continue
        if h == lb_h:
            for mi in minutes:
                if mi >= lb_m:
                    return h, mi
            continue
        return h, minutes[0]
    return None


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    minutes, hours, doms, months, dows, dom_star, dow_star = _parse(expr)

    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    if dom_star and dow_star:
        def day_ok(d):
            return True
    elif dom_star:
        def day_ok(d):
            return (d.isoweekday() % 7) in dows
    elif dow_star:
        def day_ok(d):
            return d.day in doms
    else:
        def day_ok(d):
            return d.day in doms or (d.isoweekday() % 7) in dows

    d = start.date()
    first = True
    one_day = datetime.timedelta(days=1)

    while d.year <= 3000:
        if d.month not in months:
            # Jump to the first day of the next month.
            if d.month == 12:
                d = datetime.date(d.year + 1, 1, 1)
            else:
                d = datetime.date(d.year, d.month + 1, 1)
            first = False
            continue

        if day_ok(d):
            if first:
                t = _first_time(hours, minutes, start.hour, start.minute)
            else:
                t = (hours[0], minutes[0])
            if t is not None:
                return datetime.datetime(d.year, d.month, d.day, t[0], t[1])

        d += one_day
        first = False

    raise ValueError("expression does not fire before the year 3001: %r" % expr)
```

**How it works:**

- **Parsing:** each item is matched against a strict regex that only allows ASCII digits, `*`, `-` and `/`. The parser then checks:
  - `N/S` without a range is rejected.
  - Ranges must satisfy A ≤ B.
  - Values must lie within the field's bounds.
  - The step must be at least 1.
  - In the day-of-week field, 7 is folded into 0.
- **Impossibility check:** an expression can only be unfireable when day-of-month is restricted and day-of-week is exactly `*`. In every other case some weekday or every day matches. For that case it checks whether the smallest allowed day fits into at least one allowed month. February counts as 29 days, so `0 0 29 2 *` is accepted, `0 0 31 2 *` is rejected and `0 0 30,31 2,4 *` is accepted.
- **Search:** it walks forward by day, not by minute:
  - Months that are not in the month set are skipped in one jump.
  - For a matching day, the first valid hour:minute is found directly from the sorted lists. On the starting day the search begins at the current time; on later days it starts at 00:00.
  - Leap years (including 2100 not being one) come from `datetime.date` itself.
- **Speed:** the worst realistic case is `0 0 29 2 *` across the 2100 gap (2096 → 2104). Thanks to the month skipping, that visits only a few hundred days, far below 10 ms.
